function [summary,errors]=run_q6_dom_subject001_specification()
sid='subject001';phase='dom';repo=fileparts(fileparts(fileparts(mfilename('fullpath'))));glm='C:\aliceproject\GLM';fl=fullfile(glm,'first_level');d=fullfile(fl,'nirs_spm_inputs_v2_fulltimeline_trial1',sid);nf=fullfile(d,[sid '_nirs_data.mat']);root=fullfile(repo,'results','q6_extraneous_dom','cohort_specification',sid);if ~isfolder(root),mkdir(root);end;addpath(fl);addpath(fullfile(glm,'toolboxes','spm'));addpath(genpath(fullfile(glm,'toolboxes','NIRS_SPM_v4_r1')));ev=readtable(fullfile(d,[sid '_events_used_v2.csv']),'TextType','string');ev.condition=string(ev.condition);src=["DivisionOfMesoappendixLILE","DivisionOfMesoappendixHILE","DivisionOfMesoappendixLIHE","DivisionOfMesoappendixHIHE"];sel=sortrows(ev(ismember(ev.condition,src),:),'onset_sec');assert(all(ismember(src,unique(sel.condition))));on=cell(1,4);du=cell(1,4);for i=1:4,ix=sel.condition==src(i);assert(sum(ix)==1);on{i}=double(sel.onset_sec(ix))';du{i}=double(sel.duration_sec(ix))';end;names=cellstr(src);writetable(sel,fullfile(root,[sid '_q6_dom_events_used.csv']));save(fullfile(root,[sid '_q6_dom_multiple_conditions.mat']),'names','on','du','-v7');summary=table();errors=table();
for h=["hbo","hbr"],if h=="hbo",hb="HbO";else,hb="HbR";end;hr=fullfile(root,char(hb));if ~isfolder(hr),mkdir(hr);end;try,A=specification_batch(nf,char(h),'DCT, 128','none',0,hr,0,0,1,names,on,du);X=full(A.xX.X);rn=string(A.xX.name(:));ic=contains(lower(rn),'constant');assert(size(X,2)==5&&sum(ic)==1);tx=X(:,~ic);Z=(tx-mean(tx))./std(tx,0,1);R=corrcoef(Z);mr=max(abs(R(~eye(4))));v=zeros(4,1);for j=1:4,y=tx(:,j);z=[ones(size(X,1),1),tx(:,setdiff(1:4,j))];r2=1-sum((y-z*(z\y)).^2)/sum((y-mean(y)).^2);v(j)=1/max(1-r2,eps);end;rk=rank(X);pass=rk==5&&mr<.95&&max(v)<=10;writematrix(X,fullfile(hr,[sid '_' char(hb) '_q6_dom_convolved_design.csv']));writetable(table((1:numel(rn))',rn,ic,'VariableNames',{'column_index','regressor','is_constant'}),fullfile(hr,[sid '_' char(hb) '_q6_dom_regressor_table.csv']));writetable(table(rn(~ic),v,'VariableNames',{'regressor','vif'}),fullfile(hr,[sid '_' char(hb) '_q6_dom_vif.csv']));summary=[summary;table(string(sid),hb,rk,mr,max(v),pass,'VariableNames',{'subject_id','hemoglobin','rank','max_abs_correlation','max_vif','qa_pass'})];catch ME,errors=[errors;table(string(sid),hb,string(ME.message),'VariableNames',{'subject_id','hemoglobin','error_message'})];end;end;writetable(summary,fullfile(root,[sid '_q6_dom_design_qa.csv']));writetable(errors,fullfile(root,[sid '_q6_dom_specification_errors.csv']));assert(isempty(errors));assert(all(summary.qa_pass));
end
